import sys
from math import gcd
from functools import reduce

def solve(r, c):
    if r * c < r + c:
        return "0"

    matrix = [[0] * c for _ in range(r)]
    b = list(range(1, r + c + 1))

    for i in range(r):
        for j in range(c):
            matrix[i][j] = b[i] * b[r + j]

    return "\n".join(" ".join(map(str, row)) for row in matrix)

def main():
    r, c = map(int, sys.stdin.read().strip().split())
    print(solve(r, c))

main()
